INSERT IGNORE INTO permissions (name,label) VALUES ('recruitment.manage','Konfiguracja rekrutacji'),('recruitment.review','Ocena podań rekrutacyjnych');
INSERT IGNORE INTO role_permissions (role_id,permission_id) SELECT roles.id, permissions.id FROM roles CROSS JOIN permissions WHERE roles.name IN ('administrator','owner') AND permissions.name IN ('recruitment.manage','recruitment.review');
