CREATE TABLE recruitment_settings (id INT PRIMARY KEY, title VARCHAR(120) NOT NULL, intro VARCHAR(1000) NOT NULL, is_open TINYINT NOT NULL DEFAULT 1, revision INT NOT NULL DEFAULT 1, cooldown_days INT NOT NULL DEFAULT 7) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE recruitment_ranks (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, description VARCHAR(1000) NOT NULL, active TINYINT NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 100) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE recruitment_questions (id INT AUTO_INCREMENT PRIMARY KEY, label VARCHAR(300) NOT NULL, help VARCHAR(1000) NOT NULL DEFAULT '', type VARCHAR(20) NOT NULL DEFAULT 'textarea', required TINYINT NOT NULL DEFAULT 1, active TINYINT NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 100) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE recruitment_applications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, rank_name VARCHAR(100) NOT NULL, nickname VARCHAR(64) NOT NULL, answers MEDIUMTEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'new', feedback TEXT NOT NULL, revision INT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX recruitment_user(user_id,created_at), INDEX recruitment_status(status,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE recruitment_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, status VARCHAR(20) NOT NULL, note TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX recruitment_history_application(application_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
